// Normalise chaque item brut, quelle que soit sa source, vers le schéma JSON commun (§15).
function cleanText(v) {
  if (!v) return '';
  return String(v).replace(/<[^>]*>/g, ' ').replace(/\s+/g, ' ').trim();
}

function guessWorkMode(text) {
  const t = (text || '').toLowerCase();
  if (t.includes('télétravail') || t.includes('remote') || t.includes('à distance')) return 'remote';
  if (t.includes('hybride') || t.includes('hybrid')) return 'hybrid';
  return 'onsite';
}

function guessEmploymentType(text) {
  const t = (text || '').toLowerCase();
  if (t.includes('stage') || t.includes('internship')) return 'internship';
  if (t.includes('temps partiel') || t.includes('part time') || t.includes('part-time')) return 'part_time_evening';
  if (t.includes('contrat') || t.includes('contract')) return 'contract';
  return 'full_time';
}

const TECH_KEYWORDS = [
  'Microsoft Sentinel','Sentinel','Defender XDR','Defender for Endpoint','Defender for Cloud',
  'Defender Vulnerability Management','Entra ID','Microsoft Intune','Intune','Azure','Microsoft Purview',
  'Purview','KQL','Logic Apps','SOAR','Tenable','CrowdStrike','Palo Alto','AWS Security','QRadar',
  'SIEM','EDR','XDR','IAM','PAM','CSPM','Vulnerability Management'
];

function extractTechnologies(text) {
  const t = text || '';
  return TECH_KEYWORDS.filter(k => t.toLowerCase().includes(k.toLowerCase()));
}

function mapBySource(item) {
  const src = item._source || 'Unknown';
  const now = new Date().toISOString();

  // Champs bruts possibles selon la source (RSS Job Bank / Jobillico, Greenhouse, Lever, Outlook email)
  const title = item.title || item.subject || (item.text ? item.text.split('\n')[0] : '') || '';
  const url = item.link || item.absolute_url || item.hostedUrl || item.url || '';
  const description = cleanText(item.contentSnippet || item.content || item.description || item.body || item.bodyPreview || '');
  const company = item.company || (item.categories && item.categories.department) || 'Unknown';
  const location = (item.location && item.location.name) || (item.categories && item.categories.location) || item.locationstring || '';
  const datePosted = item.pubDate || item.updated_at || item.createdAt || item.dateReceived || now;

  return {
    job_id: `${Date.now()}-${Math.random().toString(36).slice(2, 10)}`,
    source: src,
    source_job_id: String(item.id || item.guid || item.leverId || url || Math.random()),
    url: url,
    company: company,
    title: cleanText(title),
    location: cleanText(location),
    province: '',
    country: '',
    work_mode: guessWorkMode(description + ' ' + location),
    employment_type: guessEmploymentType(description),
    salary_min: null,
    salary_max: null,
    salary_currency: '',
    description: description,
    requirements: [],
    technologies: extractTechnologies(description + ' ' + title),
    certifications: [],
    languages: [],
    security_clearance: '',
    date_posted: datePosted,
    date_discovered: now,
    application_url: url,
    easy_apply: false
  };
}

return $input.all().map(i => ({ json: mapBySource(i.json) }));
